import java.nio.charset.Charset
import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter

import scala.collection.mutable
import io.circe.Json

// ============================================================================
// Protocol-like traits (structural typing counterparts)
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value: String = "string" }
  case object NUMERIC extends TokenType { val value: String = "numeric" }
  case object TEMPORAL extends TokenType { val value: String = "temporal" }
  case object STRUCTURED extends TokenType { val value: String = "structured" }
  case object BINARY extends TokenType { val value: String = "binary" }
  case object NULL extends TokenType { val value: String = "null" }

  val values: Vector[TokenType] = Vector(STRING, NUMERIC, TEMPORAL, STRUCTURED, BINARY, NULL)
}

// ============================================================================
// Core Token Classes
// ============================================================================

final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(entries: (String, Any)*): Token = {
    if (entries.isEmpty) this else copy(metadata = metadata ++ entries)
  }
}

final class MutableTokenBatch {
  private val tokens = mutable.ArrayBuffer.empty[Token]
  private var processed = false

  def add(token: Token): Unit = {
    if (processed) throw new IllegalStateException("Batch already processed")
    tokens += token
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def toVector: Vector[Token] = tokens.toVector
}

// ============================================================================
// Generic Container Classes
// ============================================================================

final class TokenContainer[+T](items: Seq[T]) {
  private val stored = items.toVector

  def getAll: Vector[T] = stored
  def mapTokens(func: T => String): List[String] = stored.map(func).toList
  def size: Int = stored.size
}

final class TokenSink[-T] {
  private val received = mutable.ArrayBuffer.empty[Any]

  def receive(item: T): Unit = received += item

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

final class BivariantHandler[T](default: T) {
  private var value: T = default

  def get: T = value
  def set(value: T): Unit = { this.value = value }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

final class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {
  private val charset = Charset.forName(encoding)

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(str) => str
      case Right(bytes) => new String(bytes, charset)
    }
    Token(normalizer(strValue), TokenType.STRING)
  }

  def tokenize(value: String): Token = tokenize(Left(value))
  def tokenize(value: Array[Byte]): Token = tokenize(Right(value))
}

final class NumericTokenizer(
    precision: Int = 6,
    // Mutable defaults are avoided in Scala; use an immutable map.
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {
  def tokenize(value: Any): Token = {
    val strValue = value match {
      case bd: BigDecimal => formatDecimal(bd)
      case bd: java.math.BigDecimal => formatDecimal(BigDecimal(bd))
      case d: Double => formatDecimal(BigDecimal(d))
      case f: Float => formatDecimal(BigDecimal.decimal(f.toDouble))
      case n: Byte => n.toString
      case n: Short => n.toString
      case n: Int => n.toString
      case n: Long => n.toString
      case n: BigInt => n.toString
      case n: java.lang.Number => n.toString
      case other => other.toString
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }

  private def formatDecimal(value: BigDecimal): String =
    value.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
}

final class TemporalTokenizer(formatStr: Option[String] = None)
    extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {
  private val isoFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val formatter = formatStr
      .map(DateTimeFormatter.ofPattern)
      .getOrElse(value match {
        case Left(_) => isoFormatter
        case Right(_) => dateFormatter
      })

    val rendered = value match {
      case Left(dt) => dt.format(formatter)
      case Right(d) => d.format(formatter)
    }

    Token(rendered, TokenType.TEMPORAL)
  }

